import{_ as c,C as i,o as l,c as n,ak as r,E as o,j as d,a}from"./chunks/framework.DxrHb2fb.js";const g=JSON.parse('{"title":"Tooltip 文字提示","description":"","frontmatter":{},"headers":[],"relativePath":"components/tooltip.md","filePath":"components/tooltip.md","lastUpdated":1790043131000}'),h={name:"components/tooltip.md"};function s(p,t,b,u,x,f){const e=i("XhDemo");return l(),n("div",null,[t[0]||(t[0]=r('<h1 id="tooltip-文字提示" tabindex="-1">Tooltip 文字提示 <a class="header-anchor" href="#tooltip-文字提示" aria-label="Permalink to &quot;Tooltip 文字提示&quot;">​</a></h1><p>悬停或聚焦时出现的一句纯文字说明。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/tooltip" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/tooltip.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/tooltip" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/tooltip" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/tooltip.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>悬停或聚焦触发器即显示；指针停在提示上也不收起</p>',5)),o(e,{src:"tooltip/01-basic"}),t[1]||(t[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;tooltip&quot;</code>：<strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>arrow</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="朝向" tabindex="-1">朝向 <a class="header-anchor" href="#朝向" aria-label="Permalink to &quot;朝向&quot;">​</a></h3><p>placement 是请求值，空间不足时由定位引擎避让；箭头跟随最终落定的一面</p>',6)),o(e,{src:"tooltip/02-placement"}),t[2]||(t[2]=d("h3",{id:"延时",tabindex:"-1"},[a("延时 "),d("a",{class:"header-anchor",href:"#延时","aria-label":'Permalink to "延时"'},"​")],-1)),t[3]||(t[3]=d("p",null,"openDelay 默认 700ms 用于防误触，closeDelay 默认 300ms 留出指针移动的余地；聚焦不经这两段等待",-1)),o(e,{src:"tooltip/03-delay"}),t[4]||(t[4]=d("h3",{id:"禁用",tabindex:"-1"},[a("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[5]||(t[5]=d("p",null,"disabled 只关闭提示本身，被包裹的触发器照常可点击、可聚焦",-1)),o(e,{src:"tooltip/04-disabled"}),t[6]||(t[6]=d("h3",{id:"颜色",tabindex:"-1"},[a("颜色 "),d("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[7]||(t[7]=d("p",null,"六种语气更换浮层实心底与其上的文字色，箭头一并随之变化；把指针停在触发器上（或用 Tab 聚焦）查看差别",-1)),o(e,{src:"tooltip/05-tone"}),t[8]||(t[8]=d("h3",{id:"尺寸",tabindex:"-1"},[a("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[9]||(t[9]=d("p",null,"三档改变浮层的内边距与字号，不写 size 即默认档；把指针停在触发器上（或用 Tab 聚焦）查看差别",-1)),o(e,{src:"tooltip/06-size"}),t[10]||(t[10]=d("h3",{id:"受控",tabindex:"-1"},[a("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[11]||(t[11]=d("p",null,"传入 open 后由宿主决定；悬停、聚焦、Escape 都只发意图，最终是否写回由外部的这份状态决定",-1)),o(e,{src:"tooltip/07-controlled"}),t[12]||(t[12]=d("h3",{id:"长文案",tabindex:"-1"},[a("长文案 "),d("a",{class:"header-anchor",href:"#长文案","aria-label":'Permalink to "长文案"'},"​")],-1)),t[13]||(t[13]=d("p",null,"提示到达宽度上限后换行，不会拉成一条横线；上限是 content 上的 --xh-tooltip-max-w 槽位",-1)),o(e,{src:"tooltip/08-long-text"}),t[14]||(t[14]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>补充说明图标按钮的含义，或截断文字的全文。</li><li>内容是纯文字，且没有任何可交互元素。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容中有按钮或链接时，使用<a href="./popover">气泡卡片</a>，提示无法交互。</li><li>信息重要到不能错过时，写在界面上，不放进悬停。</li><li>触摸设备是主要场景时，没有悬停。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>openDelay</code> / <code>closeDelay</code> 防止指针经过时连续闪烁。</li><li>聚焦也能触发，键盘用户可以访问。</li><li>语气与尺寸两轴。</li><li>默认保持反白的小型 M2 表面（compact 档 frosted），与承载操作的 Popover 分开；六种语气都使用高遮蔽 tint 与不透明文字，箭头和气泡同色同边。边界由 on 色 20% 的拼色描边承担（frosted 的透明深边压在反白底上看不见），不画顶部高光；圆角取 4px 控件档。</li><li>进退场只做侧向短移与透明度，不缩放文字和箭头：入场 <code>--xh-motion-duration-enter</code>（200ms），退场 <code>--xh-motion-duration-exit</code>（120ms），与其他锚定列表浮层同一节奏。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>挂在<a href="./icon">图标</a>按钮、<a href="./toggle">切换按钮</a>、<a href="./truncate">文本截断</a>上。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>一句话说完，超过一行应换其他形式。</li><li>必须显示较长的单句时让它在最大宽度内换行；连续长词也会断行，不会把浮层撑出窄屏。</li><li>图标按钮的可访问名称写在按钮上（<code>aria-label</code>），提示只是视觉补充。</li></ul><h3 id="当前边界" tabindex="-1">当前边界 <a class="header-anchor" href="#当前边界" aria-label="Permalink to &quot;当前边界&quot;">​</a></h3><ul><li>当前尚无 TooltipProvider，多个目标间的统一 delay、skip-delay、同组互斥与触发器滚动关闭仍是后续独立行为功能；本次不以样式模拟这些时序。</li><li>共享浮层位移原语当前最小档是 4px；Tooltip 先与 Menu 使用同一 <code>xh-overlay-slide-in/out</code> 定义。规格中的 2px 需要新增公共 motion distance 档后统一接入，不能局部改写现有语义令牌。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>把唯一的操作说明放进提示，触摸用户无法看到。</li><li>提示内放链接。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tooltip&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTooltipArrow</code> <code>XhTooltipContent</code> <code>XhTooltipPositioner</code> <code>XhTooltipRoot</code> <code>XhTooltipTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useTooltip</code></td></tr><tr><td>状态机</td><td><code>tooltipMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tooltip.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td>请求的浮层朝向，默认 bottom；空间不足时由定位引擎避让。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>浮层与锚点的间距（px）。</td></tr><tr><td><code>openDelay</code></td><td><code>number</code></td><td></td><td>悬停进入到展开的等待毫秒，默认 700。</td></tr><tr><td><code>closeDelay</code></td><td><code>number</code></td><td></td><td>悬停移出到收起的等待毫秒，默认 300。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>只关闭提示本身，不影响被包裹控件的可用性。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定提示的底色与其上的文字色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定内边距与字号档位。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: TooltipOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>TooltipOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTooltipRoot</code></td><td><code>default</code></td><td><code>TooltipRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>closed</code> · <code>opening</code> · <code>visible</code> · <code>visible.open</code> · <code>visible.closing</code></p><p><strong>事件</strong>：<code>POINTER.ENTER</code> · <code>POINTER.LEAVE</code> · <code>POINTER.DOWN</code> · <code>FOCUS</code> · <code>BLUR</code> · <code>ESCAPE</code> · <code>OPEN</code> · <code>CLOSE</code> · <code>after.openDelay</code> · <code>after.closeDelay</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isDisabled</code> · <code>isFocusOpened</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/tooltip/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>not disabled</td><td>焦点进入 trigger 立即展开、离开立即收起，都不走延时</td></tr><tr><td><code>Escape</code></td><td>展开中且本层在层栈栈顶，或 focus in trigger 且等待展开中</td><td>立即收起，不等 closeDelay；下层浮层不受这一次按键影响</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-describedby</code></td><td><code>content</code> 部件的 id | undefined</td></tr><tr><td><code>content</code></td><td><code>aria-hidden</code></td><td>!open || undefined</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/tooltip.css</code> 使用 <code>[data-scope=&quot;tooltip&quot;][data-part=&quot;trigger&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-tooltip-arrow-size</code></td><td><code>arrow</code></td><td><code>--xh-_overlay-arrow-size</code></td><td><code>default</code></td><td><code>--xh-overlay-arrow-size</code></td><td>tooltip 的 arrow 部件 --xh-_overlay-arrow-size 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-backdrop</code></td><td><code>content</code></td><td><code>-webkit-backdrop-filter</code><br><code>backdrop-filter</code></td><td><code>default</code></td><td><code>--xh-material-frosted-compact-backdrop</code></td><td>tooltip 的 content 部件 -webkit-backdrop-filter、backdrop-filter 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-bg</code></td><td><code>arrow</code><br><code>content</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tooltip-solid</code></td><td>tooltip 的 arrow、content 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-border</code></td><td><code>arrow</code><br><code>content</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-_tooltip-border</code></td><td>tooltip 的 arrow、content 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tooltip-on</code></td><td>tooltip 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-font-size</code></td><td><code>content</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_tooltip-font-size</code></td><td>tooltip 的 content 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-highlight</code></td><td><code>content</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>transparent</code></td><td>tooltip 的 content 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-layer</code></td><td><code>positioner</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>tooltip 的 positioner 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-max-w</code></td><td><code>content</code></td><td><code>max-inline-size</code></td><td><code>default</code></td><td><code>--xh-overlay-max-w</code></td><td>tooltip 的 content 部件 max-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-px</code></td><td><code>content</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_tooltip-px</code></td><td>tooltip 的 content 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-py</code></td><td><code>content</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-_tooltip-py</code></td><td>tooltip 的 content 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-radius</code></td><td><code>content</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>tooltip 的 content 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-shadow</code></td><td><code>content</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-compact-shadow</code></td><td>tooltip 的 content 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-tooltip-trigger-gap</code></td><td><code>trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-control-gap-sm</code></td><td>tooltip 的 trigger 部件 gap 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>共享关键帧 <code>xh-overlay-slide-in</code> · <code>xh-overlay-slide-out</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',59))])}const P=c(h,[["render",s]]);export{g as __pageData,P as default};
